vulnerableCode.code:
// VULNERABLE - input concatenated in, and the call runs EVERY statement in the string
const sql = "SELECT door, granted FROM door_acl WHERE badge = '" + badge + "'";
db.exec(sql); // exec runs a batch: one ';' and the attacker's second statement rides along

secureCode.code:
// SECURE - bind the value AND use an API that runs exactly ONE statement
const rows = db.prepare('SELECT door, granted FROM door_acl WHERE badge = ?').all(badge);
// prepare()/get()/all() execute a single statement - a stacked ';' becomes a syntax error, not a command.
// Least privilege backs this up: the read path's DB role should hold SELECT only, never UPDATE.

secureCodeVariants.code:
// mysql2: multipleStatements is OFF by default - keep it off, and bind the value
const conn = await mysql.createConnection({ host, user, database /* multipleStatements: false */ });
const [rows] = await conn.execute(
  'SELECT door, granted FROM door_acl WHERE badge = ?', [badge]);
// With multipleStatements:false the driver rejects a second ';' statement outright.

// PDO: use real prepared statements; one prepare() runs one statement
$pdo->setAttribute(PDO::ATTR_EMULATE_PREPARES, false);
$stmt = $pdo->prepare('SELECT door, granted FROM door_acl WHERE badge = ?');
$stmt->execute([$badge]); // a stacked ';' cannot smuggle a second command through
